using System;using System.Text;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;
namespace LWS.TruckDerby {
public enum DerbyStage{Countdown,Playing,Aftermath,Replay,HeatResult}
public sealed class DerbyMatch:SportsEventSession {
 readonly int[] cameraSpectators={-1,-1,-1,-1};
 Vector3 LiveSpectatorFocus(int view,Vector3 previousCamera){int target=cameraSpectators[view];if(target<0||target>=setup.count||fighters[target].Eliminated){target=-1;float distance=float.PositiveInfinity;for(int i=0;i<setup.count;i++)if(!fighters[i].Eliminated){float d=(fighters[i].body.position-previousCamera).sqrMagnitude;if(d<distance){distance=d;target=i;}}cameraSpectators[view]=target;}return target>=0?fighters[target].body.position:Vector3.zero;}
 public override bool BroadcastParticipantActive(int slot)=>!fighters[slot].Eliminated;
 [Range(.25f,4)] public float derbyDamageMultiplier=2;
 public DerbyFighter[] fighters;public DerbyProps props;public DerbyFxReplay fxHistory;public SportsMotionReplay replay;public DerbyDamageReplay dents;public SportsEventCamera broadcast;public Camera[] cabCameras;public SportsCabLook[] looks;public SportsCameraFit fit;public DerbyRules rules=new DerbyRules();public DerbyStage Stage{get;private set;}public float Clock{get;private set;}public float Timer{get;private set;}public int Hits{get;private set;}public int Explosions{get;private set;}public int Draws{get;private set;}public float PeakImpact{get;private set;}
 readonly string[] elimination=new string[8];readonly Vector2[] bot=new Vector2[8];readonly float[] think=new float[8],reverse=new float[8],nextDisengage=new float[8],escape=new float[8];readonly int[] owners=new int[4];readonly StringBuilder text=new StringBuilder(900);int humans;bool skip;string notice="";Vector3 cameraFocus;float replayAge;
 public override string Title=>"DEMOLITION DERBY";public override int MinimumPlayers=>2;public override int MaximumPlayers=>8;public override int OptionCount=>2;public override int WeatherCount=>1;public override bool UsesAction=>false;public override string OptionLabel=>option==0?"CAB VIEW · REAL REAR MIRRORS":"SHARED STADIUM BROADCAST";public override bool MultiViewHUD=>option==0&&humans>0&&Stage!=DerbyStage.Replay;public override bool ReplayControls=>Stage==DerbyStage.Replay;
 public override string Help=>"FIRST TO THREE HEATS · LAST TRUCK RUNNING\nActual NWH truck suspension, tires, powertrain and dents. Drive, steer and brake before reversing. Reverse rams protect the engine but the rear can still be destroyed. Front, sides, roof, wheels, engine and chassis take different damage from genuine energetic solid contact. Low-speed scrapes and sustained compound contact do not repeatedly deal damage. No second collision impulse is added.\n\nKEEP MOVING: five seconds without meaningful chassis movement causes a fiery explosion. Wheelspin and vibration do not count. The stop clock runs only in active play. Rollovers allow a short physical rocking recovery using movement, then eliminate if unrecoverable. Engine damage reduces power, wheel damage reduces control, smoke/fire warn of severe failure. The last survivor wins; equal-step final eliminations draw. After the heat locks, survivors cannot be exploded by the stop rule.\n\nUp to four local humans plus named AI. Cab right stick looks independently; assigned keyboard mouse uses RMB look, middle click recenter. Shared-controller sticks keep a fixed useful view. Rear mirrors render the owning world, at a bounded update rate. Shared stadium view retains every competitor. Replays show recorded impacts, dents and breakup, never simulated new outcomes. Offline only.";
 public override string Header=>Title+" · HEAT "+rules.Heat+" · "+(Stage==DerbyStage.Countdown?Mathf.CeilToInt(Timer).ToString():Stage==DerbyStage.Playing?rules.Remaining+" RUNNING":Stage.ToString().ToUpperInvariant());
 public override string Status=>Stage==DerbyStage.Playing?(Clock<4?"KEEP MOVING · REVERSE RAMS PROTECT YOUR ENGINE":""):notice;
 string Detail(int i){var f=fighters[i];return !rules.alive[i]?rules.reasons[i]:(f.motion.Stopped>1?"<color=#FF8645>MOVE! "+Mathf.Max(0,5-f.motion.Stopped).ToString("F1")+"s</color> · ":"")+"ENGINE "+Mathf.RoundToInt((1-f.damage.Engine)*100)+"% · BODY "+Mathf.RoundToInt((1-f.damage.Structure)*100)+"%";}
 public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append(setup.players[i].name).Append(" · ").Append(rules.wins[i]).Append(" / 3 · ").Append(Detail(i)).Append('\n');return text.ToString();}}
 public override string Results=>setup.players[Mathf.Max(0,rules.Winner)].name+" WINS THE DERBY\n\n"+Standings+"\nActual qualifying impacts: "+Hits+" · Explosions: "+Explosions+" · Drawn heats: "+Draws;
 public override string ViewText(int view){int i=owners[Mathf.Clamp(view,0,3)];return setup.players[i].name+" · "+rules.wins[i]+" / 3 · "+Mathf.Max(0,rules.Remaining-(rules.alive[i]?1:0))+" OPPONENTS\n"+Detail(i)+"\n"+Controls(i);}
 public override float ParticipantProgress(int slot)=>rules.alive[slot]?fighters[slot].motion.Stopped/5:-1;
 public override bool ValidateSources(out string reason){if(!base.ValidateSources(out reason))return false;int n=0;for(int i=0;i<setup.count;i++)if(setup.players[i].source!=BowlingSource.AI)n++;if(n>4){reason="Up to four local human drivers; remaining seats use AI.";return false;}return true;}
 protected override void BeginGame(){rules.Reset(setup.count);Hits=Explosions=Draws=0;PeakImpact=0;BeginHeat();}
 int VisibleMask()=>((1<<setup.count)-1)|(props!=null?props.Mask:0);
 void BeginHeat(){replay.End();fxHistory.ResetRecord();props?.ResetProps();dents.ResetRecord();Stage=DerbyStage.Countdown;Timer=3;Clock=0;skip=false;notice="KEEP MOVING TO SURVIVE";Array.Clear(elimination,0,elimination.Length);for(int i=0;i<8;i++){fighters[i].gameObject.SetActive(i<setup.count);if(i>=setup.count)continue;float a=i*Mathf.PI*2/setup.count;var p=new Vector3(Mathf.Sin(a)*29,1.3f,Mathf.Cos(a)*29);fighters[i].ResetFighter(p,Quaternion.LookRotation(new Vector3(p.x,0,p.z)));think[i]=reverse[i]=nextDisengage[i]=escape[i]=0;bot[i]=Vector2.zero;}for(int i=0;i<setup.count;i++){var color=new MaterialPropertyBlock();color.SetColor("_BaseColor",setup.players[i].color);foreach(var renderer in replay.ghosts[i].GetComponentsInChildren<Renderer>(true))if(renderer.name=="Cab"||renderer.name=="Wreck piece · Cab")renderer.SetPropertyBlock(color);}replay.ResetRecord();dents.CaptureBaseline();Layout();Gate();}
 void Layout(){humans=SportsCameraOptions.Select(setup,owners);foreach(var c in cabCameras)c.enabled=false;bool cab=option==0&&humans>0;broadcast.view.enabled=!cab;if(cab){cameras=new Camera[humans];for(int v=0;v<humans;v++){cameras[v]=cabCameras[v];cabCameras[v].enabled=true;cabCameras[v].rect=LWS.TruckCornhole.CornholeMatch.ViewRect(humans,v);looks[v].ResetLook();}}else{cameras=new[]{broadcast.view};broadcast.view.rect=new Rect(0,0,1,1);}foreach(var f in fighters)f.mirrors.Show(false);cameraFocus=Vector3.zero;}
 public void QueueElimination(int slot,string reason){if(Stage==DerbyStage.Playing&&rules.alive[slot]&&elimination[slot]==null)elimination[slot]=reason;}
 public void Hit(int slot,int other,float speed,float intensity,Vector3 point){Hits++;PeakImpact=Mathf.Max(PeakImpact,speed);feedback.Play(1,speed);Pulse(slot,Mathf.Min(.7f,intensity),.12f);dents.Request(slot,Clock+.35f);}
 void Eliminations(){int mask=0;for(int i=0;i<setup.count;i++)if(elimination[i]!=null&&rules.Eliminate(i,elimination[i]))mask|=1<<i;for(int i=0;i<setup.count;i++)if((mask&(1<<i))!=0){fighters[i].Eliminate(elimination[i]);Explosions++;var p=fighters[i].body.worldCenterOfMass;for(int j=0;j<setup.count;j++)if(rules.alive[j]&&!fighters[j].body.isKinematic){float d=Vector3.Distance(p,fighters[j].body.worldCenterOfMass);if(d<9)fighters[j].body.AddExplosionForce(fighters[j].body.mass*5,p,9,1,ForceMode.Impulse);}}Array.Clear(elimination,0,elimination.Length);}
 Vector2 AI(int slot,float dt){var f=fighters[slot];think[slot]-=dt;reverse[slot]=Mathf.Max(0,reverse[slot]-dt);escape[slot]=Mathf.Max(0,escape[slot]-dt);if(f.motion.Stopped>1.5f&&reverse[slot]<=0)reverse[slot]=1.2f;if(f.ContactAge>1.4f&&Time.fixedTime-f.LastImpact>1.2f&&Clock>=nextDisengage[slot]){escape[slot]=3;nextDisengage[slot]=Clock+4.5f;}if(think[slot]>0)return bot[slot];float skill=(int)setup.players[slot].difficulty;think[slot]=Mathf.Lerp(.25f,.07f,skill*.5f);int target=-1;float best=float.MaxValue;for(int i=0;i<setup.count;i++)if(i!=slot&&rules.alive[i]){float d=(fighters[i].body.position-f.body.position).sqrMagnitude*(1+fighters[i].damage.Structure*.2f);if(d<best){best=d;target=i;}}if(target<0)return Vector2.zero;var p=f.body.position;var t=fighters[target];if(escape[slot]>0){var away=Vector3.ProjectOnPlane(p-t.body.position,Vector3.up).normalized;if(away.sqrMagnitude<.1f)away=Quaternion.Euler(0,slot*45,0)*Vector3.right;if(new Vector2(p.x+away.x*10,p.z+away.z*10).magnitude>42)away=Vector3.ProjectOnPlane(away-p.normalized*1.5f,Vector3.up).normalized;bool retreatBack=Vector3.Dot(f.transform.forward,away)<0;var heading=retreatBack?-f.transform.forward:f.transform.forward;float retreatAngle=Vector3.SignedAngle(Vector3.ProjectOnPlane(heading,Vector3.up),away,Vector3.up);bot[slot]=new Vector2(Mathf.Clamp(retreatAngle/35,-1,1)*(retreatBack?-1:1),retreatBack?-.95f:1);return bot[slot];}var aim=t.body.position+Vector3.ProjectOnPlane(t.body.linearVelocity,Vector3.up)*Mathf.Lerp(.05f,.4f,skill*.5f);aim+=new Vector3(Mathf.Sin(Clock*.7f+slot*3),0,Mathf.Cos(Clock*.6f+slot*7))*Mathf.Lerp(3,.4f,skill*.5f);var delta=aim-p;delta.y=0;bool backing=Clock<4&&Vector3.Dot(f.transform.forward,delta.normalized)<-.15f||reverse[slot]>0||f.damage.Engine>.5f&&Vector3.Dot(f.transform.forward,delta.normalized)<-.2f;var forward=backing?-f.transform.forward:f.transform.forward;float angle=Vector3.SignedAngle(Vector3.ProjectOnPlane(forward,Vector3.up),delta,Vector3.up);float steering=Mathf.Clamp(angle/40,-1,1)*(backing?-1:1);float throttle=backing?-.9f:Mathf.Abs(angle)>75?.45f:1;if(p.sqrMagnitude>43*43){delta=-p;delta.y=0;angle=Vector3.SignedAngle(Vector3.ProjectOnPlane(f.transform.forward,Vector3.up),delta,Vector3.up);steering=Mathf.Clamp(angle/32,-1,1);throttle=.8f;}bot[slot]=new Vector2(steering,throttle);return bot[slot];}
 protected override void Simulate(float dt){if(Stage==DerbyStage.Countdown){Timer-=dt;if(Timer<=0){for(int i=0;i<setup.count;i++)fighters[i].Wake();Stage=DerbyStage.Playing;}return;}if(Stage==DerbyStage.Playing){Clock+=dt;for(int i=0;i<setup.count;i++)if(rules.alive[i])fighters[i].Drive(setup.players[i].source==BowlingSource.AI?AI(i,dt):commands[i],dt);Eliminations();dents.Tick(Clock);replay.Record(Clock,VisibleMask());fxHistory.Record(Clock);if(rules.FinishStep()){if(rules.HeatWinner<0)Draws++;notice=rules.HeatWinner<0?"SIMULTANEOUS WIPE · DRAW":setup.players[rules.HeatWinner].name+" SURVIVES THE HEAT";Stage=DerbyStage.Aftermath;Timer=2.5f;foreach(var f in fighters){f.vehicle.input.states.Reset();f.vehicle.enabled=false;f.mirrors.Show(false);}}return;}if(Stage==DerbyStage.Aftermath){Clock+=dt;Timer-=dt;dents.Tick(Clock);replay.Record(Clock,VisibleMask());fxHistory.Record(Clock);if(Timer<=0){props?.Hide();foreach(var f in fighters){f.Freeze();f.gameObject.SetActive(false);}Stage=DerbyStage.Replay;replayAge=0;replay.Begin(Mathf.Max(0,Clock-10));dents.Draw(replay.Cursor);feedback.Play(5,0,true);}return;}if(Stage==DerbyStage.Replay){replayAge+=dt;dents.Draw(replay.Cursor);if(skip||replay.Step(dt)||replayAge>14){replay.End();fxHistory.Hide();Stage=DerbyStage.HeatResult;Timer=2;}return;}Timer-=dt;if(Timer<=0){if(rules.Winner>=0)EndMatch();else{rules.NextHeat();BeginHeat();}}}
 protected override void Present(float dt){bool cab=option==0&&humans>0&&Stage!=DerbyStage.Replay;if(cab){int mouseOwner=-1;for(int v=0;v<humans;v++)if(setup.players[owners[v]].source==BowlingSource.Keyboard){mouseOwner=owners[v];break;}for(int v=0;v<humans;v++){int slot=owners[v];var f=fighters[slot];var c=cabCameras[v];if(f.Eliminated){f.mirrors.Show(false);c.transform.SetPositionAndRotation(LiveSpectatorFocus(v,c.transform.position)+new Vector3(0,9,-15),Quaternion.LookRotation(new Vector3(0,-7,15)));continue;}var basis=f.body.rotation;c.transform.position=f.cabSeat.position;c.transform.rotation=looks[v].Apply(basis,setup.players[slot],slot,slot==mouseOwner,Live&&Stage==DerbyStage.Playing,SportsLookOptions.Sensitivity,SportsLookOptions.InvertY);f.mirrors.Show(Live&&Stage==DerbyStage.Playing);}}else{broadcast.view.enabled=true;foreach(var c in cabCameras)c.enabled=false;if(Stage==DerbyStage.Replay&&replay.Playing){if(cameras.Length!=1||cameras[0]!=broadcast.view)cameras=new[]{broadcast.view};fxHistory.Draw(replay.Cursor);Vector3 p=replay.Position(Mathf.Max(0,rules.HeatWinner));broadcast.view.orthographic=false;broadcast.Pose(p+Vector3.up*1.5f,replay.Angle%3==0?new Vector3(19,11,-20):replay.Angle%3==1?new Vector3(-20,5,9):new Vector3(0,38,-3),62);return;}broadcast.view.orthographic=true;var bounds=new Bounds(Vector3.zero,new Vector3(78,12,78));for(int i=0;i<setup.count;i++)if(rules.alive[i])bounds.Encapsulate(fighters[i].body.position);var target=bounds.center;cameraFocus=Vector3.Lerp(cameraFocus,target,1-Mathf.Exp(-dt*1.5f));broadcast.Pose(cameraFocus,new Vector3(0,65,-85),65);fit.arenaBounds=bounds;fit.Apply();}}
 public override void ExtraAction(string key){if(Stage!=DerbyStage.Replay)return;if(key=="replayangle")replay.Angle=(replay.Angle+1)%3;else if(key=="replayspeed")replay.Speed=replay.Speed==1?.5f:replay.Speed==.5f?2:1;else if(key=="replayrewind"){replay.Seek(Mathf.Max(0,replay.Cursor-3));dents.Draw(replay.Cursor);}else if(key=="replayskip")skip=true;ConsumeActions();}
 protected override void SetPaused(bool paused){if(paused&&fighters!=null)foreach(var f in fighters)if(f!=null)f.mirrors.Show(false);if(paused&&looks!=null)foreach(var l in looks)if(l!=null)l.ReleaseCursor();}
 protected override void StopGame(){replay?.End();fxHistory?.Hide();props?.Freeze();if(fighters!=null)foreach(var f in fighters)if(f!=null)f.Freeze();}protected override void StopSounds(){if(fighters!=null)foreach(var f in fighters)if(f!=null)f.StopSound();}
}}
